import itertools
from pysat.formula import CNF
from pysat.solvers import Solver

# 9 vertices, need min degree >= 5
fixed_edges = [(5,7), (1,5), (3,6), (5,6), (4,5), (4,6), (0,7)]

all_possible_edges = [(i, j) for i in range(9) for j in range(i+1, 9)]
remaining_edges = [e for e in all_possible_edges if e not in fixed_edges]

print(f"Total possible edges: {len(all_possible_edges)}")
print(f"Fixed edges: {len(fixed_edges)}")
print(f"Remaining edges: {len(remaining_edges)}")

# Map edges to variables
edge_to_var = {}
var_to_edge = {}
for idx, e in enumerate(remaining_edges):
    var = idx + 1
    edge_to_var[e] = var
    var_to_edge[var] = e

n_vars = len(remaining_edges)

# Current degrees from fixed edges
fixed_degree = {i: 0 for i in range(9)}
for u, v in fixed_edges:
    fixed_degree[u] += 1
    fixed_degree[v] += 1

print("Fixed degrees:", fixed_degree)

cnf = CNF()

# For each vertex, we need degree >= 5
for v in range(9):
    needed = max(0, 5 - fixed_degree[v])
    if needed > 0:
        incident_vars = []
        for e in remaining_edges:
            if e[0] == v or e[1] == v:
                incident_vars.append(edge_to_var[e])

        print(f"Vertex {v}: needs {needed} more, has {len(incident_vars)} incident remaining edges")

        if needed > len(incident_vars):
            print(f"  -> UNSAT: not enough edges")
            break

        # At least 'needed' out of len(incident_vars) must be true
        # Encoding: for any subset of size (len - needed + 1), at least one must be true
        # i.e., we cannot have (len - needed + 1) false variables
        from itertools import combinations
        for combo in combinations(incident_vars, len(incident_vars) - needed + 1):
            cnf.append([v for v in combo])

print(f"CNF has {len(cnf.clauses)} clauses")

solver = Solver()
solver.append_formula(cnf)

if solver.solve():
    model = solver.get_model()
    chosen_edges = list(fixed_edges)
    for var in model:
        if var > 0:
            e = var_to_edge[var]
            chosen_edges.append(e)

    print(f"\nSolution found with {len(chosen_edges)} edges")
    print("Edges:", sorted(chosen_edges))

    deg = {i: 0 for i in range(9)}
    for u, v in chosen_edges:
        deg[u] += 1
        deg[v] += 1
    print("Degrees:", deg)
    print("Min degree:", min(deg.values()))

    # Check for triangles
    adj = {i: set() for i in range(9)}
    for u, v in chosen_edges:
        adj[u].add(v)
        adj[v].add(u)

    triangles = []
    for i in range(9):
        for j in adj[i]:
            if j > i:
                for k in adj[j]:
                    if k > j and k in adj[i]:
                        triangles.append((i, j, k))
    print(f"Triangles found: {triangles}")
else:
    print("UNSATISFIABLE")
